CREATE TABLE "User" ("id" TEXT NOT NULL, "email" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "name" TEXT NOT NULL, "role" TEXT NOT NULL DEFAULT 'ADMIN', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProductCategory" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, CONSTRAINT "ProductCategory_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Product" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT NOT NULL, "price" INTEGER NOT NULL, "unit" TEXT NOT NULL, "image" TEXT NOT NULL, "stock" INTEGER NOT NULL DEFAULT 0, "active" BOOLEAN NOT NULL DEFAULT true, "fresh" BOOLEAN NOT NULL DEFAULT false, "storage" TEXT, "categoryId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Product_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Order" ("id" TEXT NOT NULL, "orderNumber" TEXT NOT NULL, "recipient" TEXT NOT NULL, "phone" TEXT NOT NULL, "address" TEXT NOT NULL, "delivery" TEXT NOT NULL, "shipWeek" TEXT NOT NULL, "paymentMethod" TEXT NOT NULL, "paymentStatus" TEXT NOT NULL DEFAULT 'TEST_PENDING', "status" TEXT NOT NULL DEFAULT 'PENDING', "subtotal" INTEGER NOT NULL, "shipping" INTEGER NOT NULL, "total" INTEGER NOT NULL, "ripenessConfirmed" BOOLEAN NOT NULL DEFAULT false, "trackingNumber" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Order_pkey" PRIMARY KEY ("id"));
CREATE TABLE "OrderItem" ("id" TEXT NOT NULL, "orderId" TEXT NOT NULL, "productId" TEXT NOT NULL, "productName" TEXT NOT NULL, "unitPrice" INTEGER NOT NULL, "quantity" INTEGER NOT NULL, CONSTRAINT "OrderItem_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Experience" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "price" INTEGER NOT NULL, "capacity" INTEGER NOT NULL DEFAULT 12, "active" BOOLEAN NOT NULL DEFAULT true, CONSTRAINT "Experience_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Booking" ("id" TEXT NOT NULL, "reference" TEXT NOT NULL, "experienceId" TEXT NOT NULL, "date" TIMESTAMP(3) NOT NULL, "slot" TEXT NOT NULL, "people" INTEGER NOT NULL, "name" TEXT NOT NULL, "phone" TEXT NOT NULL, "note" TEXT, "status" TEXT NOT NULL DEFAULT 'PENDING', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Booking_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Article" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "slug" TEXT NOT NULL, "body" TEXT NOT NULL, "image" TEXT, "published" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Article_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Recipe" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "ingredients" JSONB NOT NULL, "steps" JSONB NOT NULL, "image" TEXT, "published" BOOLEAN NOT NULL DEFAULT false, CONSTRAINT "Recipe_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CultureSpot" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "address" TEXT NOT NULL, "description" TEXT NOT NULL, "latitude" DOUBLE PRECISION, "longitude" DOUBLE PRECISION, "image" TEXT, CONSTRAINT "CultureSpot_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Announcement" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "body" TEXT NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Announcement_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SiteSetting" ("key" TEXT NOT NULL, "value" TEXT NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SiteSetting_pkey" PRIMARY KEY ("key"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE UNIQUE INDEX "ProductCategory_name_key" ON "ProductCategory"("name");
CREATE UNIQUE INDEX "Order_orderNumber_key" ON "Order"("orderNumber");
CREATE UNIQUE INDEX "Booking_reference_key" ON "Booking"("reference");
CREATE INDEX "Booking_experienceId_date_slot_status_idx" ON "Booking"("experienceId","date","slot","status");
CREATE UNIQUE INDEX "Article_slug_key" ON "Article"("slug");
ALTER TABLE "Product" ADD CONSTRAINT "Product_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "ProductCategory"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "OrderItem" ADD CONSTRAINT "OrderItem_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "OrderItem" ADD CONSTRAINT "OrderItem_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Booking" ADD CONSTRAINT "Booking_experienceId_fkey" FOREIGN KEY ("experienceId") REFERENCES "Experience"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
